const enfermedadData=[{"disease":"Salí de la reunión con un compromiso que no quería","characteristic":"Se decidió en caliente: faltó la regla de las 24 horas","opts":["Se decidió en caliente: faltó la regla de las 24 horas","La oferta era demasiado buena","Falta de información técnica","Mala suerte"]},{"disease":"Me costó decir no porque me habían hecho un favor antes","characteristic":"Reciprocidad: el regalo previo pesó más que el análisis","opts":["Reciprocidad: el regalo previo pesó más que el análisis","Prueba social: otros ya habían aceptado","Autoridad: tenía un cargo alto","Escasez: se acababa el tiempo"]},{"disease":"Acepté porque «todos los demás ya estaban adentro»","characteristic":"Prueba social sin verificar: nunca se pidió la lista","opts":["Prueba social sin verificar: nunca se pidió la lista","Simpatía por el vendedor","Anclaje del primer precio","Coherencia con un sí anterior"]},{"disease":"El precio que me pareció caro terminó pareciéndome normal","characteristic":"Anclaje: el primer número movió tu referencia","opts":["Anclaje: el primer número movió tu referencia","Escasez del producto","Autoridad del vendedor","Reciprocidad de un regalo"]},{"disease":"Me convencieron con palabras que no entendí","characteristic":"Autoridad fabricada: el tecnicismo sirvió para que no preguntaras","opts":["Autoridad fabricada: el tecnicismo sirvió para que no preguntaras","Prueba social de expertos","Simpatía del trato","Escasez del cupo"]},{"disease":"Dije sí a algo chico y terminé metido en algo grande","characteristic":"Pie en la puerta: el sí pequeño se cobró después","opts":["Pie en la puerta: el sí pequeño se cobró después","Puerta en la cara","Prueba social inflada","Urgencia fabricada"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

