const identifyTaskDB=[{"s":"Le dan una muestra gratis y después le proponen el contrato.","type":"Reciprocidad"},{"s":"Le recuerdan que ya había dicho que le interesaba, para que firme.","type":"Compromiso y coherencia"},{"s":"Le aseguran que todos los colegios del municipio ya aceptaron.","type":"Prueba social"},{"s":"Le hablan con tecnicismos y no explican nada en simple.","type":"Autoridad"},{"s":"Lo elogian y le dicen que ustedes dos son iguales.","type":"Simpatía"},{"s":"Le dicen que quedan dos cupos y que cierran hoy.","type":"Escasez"},{"s":"El primer precio que mencionan es altísimo y todo lo demás parece barato.","type":"Anclaje"},{"s":"Usted pide un día para pensarlo antes de comprometerse.","type":"Regla de las 24 horas"}];
