const evalTFBank=[{"q":"Persuadir y manipular son lo mismo con distinto nombre.","a":false},{"q":"La reciprocidad hace que un favor previo pese al decidir.","a":true},{"q":"«Quedan dos cupos» es la palanca de escasez.","a":true},{"q":"El pie en la puerta empieza con una petición enorme.","a":false},{"q":"Nombrar en voz alta la palanca reduce su efecto.","a":true},{"q":"Un límite real se cae cuando pides 24 horas para pensar.","a":false},{"q":"La autoridad se puede fabricar con tecnicismos.","a":true},{"q":"La prueba social honesta se puede verificar con nombres.","a":true},{"q":"El anclaje se defiende llegando con tu propio número calculado.","a":true},{"q":"Usar palancas siempre es manipular.","a":false},{"q":"El anclaje pierde fuerza si llegas con tu propio número ya calculado.","a":true},{"q":"Agradecer el regalo y decidir aparte es el antídoto de la reciprocidad.","a":true},{"q":"Que alguien se moleste porque le piden explicar en una frase simple habla bien de su autoridad.","a":false},{"q":"Un piloto pequeño y reversible permite decir sí sin quedar amarrado.","a":true},{"q":"Aceptar un patrocinio obliga siempre a ceder el nombre del proyecto.","a":false}];
const evalMCBank=[{"q":"¿Cuál es la prueba que separa persuadir de manipular?","o":["a) Si funciona","b) Si hay contrato","c) Si es en persona","d) Si la otra persona, sabiéndolo todo, seguiría diciendo sí"],"a":3},{"q":"Un regalo antes de pedir activa…","o":["a) Escasez","b) Reciprocidad","c) Autoridad","d) Anclaje"],"a":1},{"q":"«Todos los colegas ya firmaron» es…","o":["a) Autoridad","b) Simpatía","c) Prueba social","d) Escasez"],"a":2},{"q":"El antídoto de la urgencia fabricada es…","o":["a) Negociar el precio","b) Nombrarla y pedir 24 horas","c) Aceptar rápido","d) Cambiar de tema"],"a":1},{"q":"El pie en la puerta consiste en…","o":["a) Conseguir un sí pequeño para lograr el grande","b) Pedir mucho primero","c) Regalar algo","d) Mostrar credenciales"],"a":0},{"q":"Hablar con tecnicismos para que no pregunten es…","o":["a) Autoridad fabricada","b) Prueba social","c) Reciprocidad","d) Coherencia"],"a":0},{"q":"El anclaje se refiere a…","o":["a) La marca del producto","b) El primer número, que marca la conversación","c) El plazo de pago","d) El testimonio inicial"],"a":1},{"q":"¿Cuál es un uso honesto de la palanca de prueba social?","o":["a) Inflar la cifra de usuarios","b) Comprar testimonios","c) Insinuar que todos entraron","d) Mostrar escuelas reales con resultados verificables"],"a":3},{"q":"Si alguien se incomoda porque pides un día para pensar, eso indica…","o":["a) Que la oferta es buena","b) Que hay que decidir ya","c) Que la urgencia probablemente era fabricada","d) Que el precio va a subir"],"a":2},{"q":"¿Para qué estudia un docente las palancas de influencia?","o":["a) Para defenderse de la presión y convencer con la verdad","b) Para vender más caro","c) Para ganar discusiones","d) Para evitar negociar"],"a":0},{"q":"¿Cuál es el antídoto de la palanca de simpatía?","o":["a) Cortar la relación","b) Separar a la persona del contenido de la oferta","c) Devolver el halago","d) Firmar rápido para no incomodar"],"a":1},{"q":"Entrar a una negociación con un número propio ya calculado sirve para…","o":["a) Caer mejor","b) Ganar tiempo","c) Neutralizar el anclaje del otro","d) Subir el precio"],"a":2},{"q":"«Usted mismo dijo que quería premios para los niños» activa la palanca de…","o":["a) Coherencia","b) Escasez","c) Reciprocidad","d) Simpatía"],"a":0},{"q":"Antes de aceptar, ¿qué se pide siempre por escrito?","o":["a) La fecha de la próxima reunión","b) El nombre del asesor","c) El logo en alta resolución","d) Costo total, quién responde si falla y qué se compromete a cambio"],"a":3},{"q":"Un patrocinio local es aceptable cuando…","o":["a) Lo pide una autoridad","b) Las reglas son públicas e iguales para cualquier otro","c) Es el que más paga","d) Hay que decidir esa misma semana"],"a":1}];
const evalCPBank=[{"q":"Devolver lo recibido es la palanca de la ___.","a":"reciprocidad"},{"q":"«Solo por hoy» apela a la ___.","a":"escasez"},{"q":"Los títulos y tecnicismos activan la ___.","a":"autoridad"},{"q":"Sostener lo que ya dijimos es la palanca de la ___.","a":"coherencia"},{"q":"Decir sí a quien nos cae bien es la palanca de la ___.","a":"simpatía"},{"q":"Si otros como yo lo hacen es la prueba ___.","a":"social"},{"q":"El primer número que se dice funciona como ___.","a":"anclaje"},{"q":"La defensa más simple es la regla de las ___ horas.","a":"24"},{"q":"Conseguir un sí pequeño para el grande es el ___ en la puerta.","a":"pie"},{"q":"Manipular es conseguir un sí ___ lo importante.","a":"escondiendo"},{"q":"Pedir la lista y hablar con alguien de la lista es el antídoto de la prueba ___.","a":"social"},{"q":"Un piloto pequeño y ___ permite decir sí sin quedar amarrado.","a":"reversible"},{"q":"La autoridad real explica lo suyo en una frase ___.","a":"simple"},{"q":"Reconocer, nombrar, pedir y ___ son las cuatro frases del guion de defensa.","a":"condicionar"},{"q":"Si la oferta se cae solo porque pediste un día, era una ___.","a":"trampa"}];
const evalPRBank=[{"term":"Reciprocidad","def":"El favor previo crea una deuda que pesa al decidir"},{"term":"Coherencia","def":"Sostenemos lo que ya dijimos, aunque cambie el contexto"},{"term":"Prueba social","def":"Si otros como yo lo hacen, parece seguro"},{"term":"Autoridad","def":"Obediencia por señales de experiencia, no por argumento"},{"term":"Simpatía","def":"El sí llega más fácil por la relación que por el fondo"},{"term":"Escasez","def":"Perder pesa más que ganar: plazos y cupos"},{"term":"Anclaje","def":"El primer número marca toda la conversación"},{"term":"Regla de las 24 horas","def":"Ninguna decisión importante en caliente"},{"term":"Pie en la puerta","def":"Un sí pequeño que después se cobra como uno grande"},{"term":"Guion de cuatro frases","def":"Reconocer, nombrar, pedir y condicionar"},{"term":"Urgencia fabricada","def":"Un plazo que no resiste que lo verifiques"},{"term":"Autoridad prestada","def":"Invocar un título o un tecnicismo en vez de explicar"},{"term":"Piloto reversible","def":"Decir sí en pequeño, pudiendo deshacerlo"},{"term":"Condición por escrito","def":"Lo que convierte un sí de palabra en un acuerdo"},{"term":"La pregunta que decide","def":"Si lo supiera todo, ¿seguiría diciendo que sí?"}];

function genEval(){sfx('click');_evalFormaSelector();const _selF=document.getElementById('evalFormaSel');if(_selF&&parseInt(_selF.value,10))evalFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_selF.value,10)));const cf=evalFormNum;const rng=_evalRng(cf);window._currentEvalForm=cf;evalFormNum=(evalFormNum%EVAL_FORMAS)+1;_evalFormaSelector();saveProgress();document.getElementById('eval-screen-title').textContent=`🎓 Evaluación Final · Forma ${cf} · Las seis palancas · Ruta de la Persuasión`;evalAnsVisible=false;const out=document.getElementById('evalOut');out.innerHTML='';const bar=document.createElement('div');bar.className='eval-score-bar';bar.innerHTML=`<div><div class="esb-title">📊 Distribución de puntaje · 100 puntos</div><div class="esb-dist">Cada sección vale 25 puntos (5 preguntas × 5 pts)</div></div><div style="display:flex;gap:0.4rem;flex-wrap:wrap;"><span class="eval-score-pill esp-cp">Completar 25 pts</span><span class="eval-score-pill esp-tf">V/F 25 pts</span><span class="eval-score-pill esp-mc">Selección 25 pts</span><span class="eval-score-pill esp-pr">Pareados 25 pts</span></div>`;out.appendChild(bar);const cpItems=_pickF(evalCPBank,5,rng);const s1=document.createElement('div');s1.innerHTML='<div class="eval-section-title">I. Completar el espacio <span class="eval-pts">25 pts · 5 pts c/u</span></div>';cpItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='cp';d.dataset.evalIndex=i;const qHtml=item.q.replace('___',`<input class="eval-cp-input" type="text" data-cp="${i}" autocomplete="off">`);d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+1}</span><span class="eval-q-text">${qHtml}</span></div><div class="eval-answer">${item.a}</div><div class="eval-item-feedback" id="evalFbCp${i}" aria-live="polite"></div>`;s1.appendChild(d);});out.appendChild(s1);const tfItems=_pickF(evalTFBank,5,rng);const s2=document.createElement('div');s2.innerHTML='<div class="eval-section-title">II. Verdadero o Falso <span class="eval-pts">25 pts · 5 pts c/u</span></div>';tfItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='tf';d.dataset.evalIndex=i;d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+6}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-tf-opts"><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="true"> Verdadero</label><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="false"> Falso</label></div><div class="eval-answer">${item.a?'Verdadero':'Falso'}</div><div class="eval-item-feedback" id="evalFbTf${i}" aria-live="polite"></div>`;s2.appendChild(d);});out.appendChild(s2);const mcItems=_pickF(evalMCBank,5,rng);const s3=document.createElement('div');s3.innerHTML='<div class="eval-section-title">III. Selección Múltiple <span class="eval-pts">25 pts · 5 pts c/u</span></div>';mcItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='mc';d.dataset.evalIndex=i;const optsHtml=item.o.map((op,oi)=>`<label class="eval-mc-opt"><input type="radio" name="mc${i}" value="${oi}"> ${op}</label>`).join('');d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+11}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-mc-opts">${optsHtml}</div><div class="eval-answer">${item.o[item.a]}</div><div class="eval-item-feedback" id="evalFbMc${i}" aria-live="polite"></div>`;s3.appendChild(d);});out.appendChild(s3);const prItems=_pickF(evalPRBank,5,rng);let shuffledDefs=_shuffleF(prItems,rng);let _prTries=0;while(shuffledDefs.some((df,ix)=>df.def===prItems[ix].def)&&_prTries<20){shuffledDefs=_shuffleF(shuffledDefs,rng);_prTries++;}const letters=['A','B','C','D','E'];const s4=document.createElement('div');s4.innerHTML='<div class="eval-section-title">IV. Términos Pareados <span class="eval-pts">25 pts · 5 pts c/u</span></div>';const matchCard=document.createElement('div');matchCard.className='eval-item';let colLeft='<div class="eval-match-col"><h4>📌 Términos</h4>';prItems.forEach((item,i)=>{colLeft+=`<div class="eval-match-item"><span class="eval-match-letter">${i+16}.</span> <select class="eval-match-select" data-pr="${i}" aria-label="Respuesta pareada ${i+16}"><option value="">?</option>${letters.map(l=>`<option value="${l}">${l}</option>`).join('')}</select> ${item.term}</div>`;});colLeft+='</div>';let colRight='<div class="eval-match-col"><h4>🔑 Definiciones</h4>';shuffledDefs.forEach((item,i)=>{colRight+=`<div class="eval-match-item"><span class="eval-match-letter">${letters[i]}.</span> ${item.def}</div>`;});colRight+='</div>';const ansKey=prItems.map((item,i)=>{const letter=letters[shuffledDefs.findIndex(d=>d.def===item.def)];return`${i+16}→${letter}`;}).join(' · ');matchCard.innerHTML=`<div class="eval-match-grid">${colLeft}${colRight}</div><div class="eval-answer" style="display:none;">${ansKey}</div><div class="eval-item-feedback" id="evalFbPr" aria-live="polite"></div>`;s4.appendChild(matchCard);out.appendChild(s4);window._evalPrintData={tf:tfItems,mc:mcItems,cp:cpItems,pr:{terms:prItems,shuffledDefs,letters}};const autoPanel=document.createElement('div');autoPanel.id='evalAutoResult';autoPanel.className='eval-auto-result';autoPanel.innerHTML='<strong>🧮 Evaluación interactiva:</strong> responde en pantalla y presiona <em>Calificar prueba</em>. La impresión conserva el formato original sin respuestas digitadas.';out.appendChild(autoPanel);fin('s-evaluacion');}
function toggleEvalAns(){evalAnsVisible=!evalAnsVisible;document.querySelectorAll('#evalOut .eval-answer').forEach(el=>el.style.display=evalAnsVisible?'block':'none');sfx('click');}
function normalizeEvalAnswer(v){return(v||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').replace(/[()]/g,'').trim();}
function isCpCorrect(student,expected){const s=normalizeEvalAnswer(student);const e=normalizeEvalAnswer(expected);if(!s)return false;const variants=new Set([e]);if(e.includes(' '))e.split(' ').forEach(x=>x&&variants.add(x));return variants.has(s)||e.replace(/[^a-z0-9]/g,'')===s.replace(/[^a-z0-9]/g,'');}
function setEvalFeedback(id,ok,msg){const el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='eval-item-feedback '+(ok?'eval-ok':'eval-no');}
function gradeEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const d=window._evalPrintData;let total=0;const detail={cp:0,tf:0,mc:0,pr:0};d.cp.forEach((it,i)=>{const input=document.querySelector(`[data-cp="${i}"]`);const ok=isCpCorrect(input?input.value:'',it.a);if(input){input.classList.toggle('eval-input-ok',ok);input.classList.toggle('eval-input-no',!ok);}if(ok){detail.cp++;total+=5;}setEvalFeedback('evalFbCp'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.a);});d.tf.forEach((it,i)=>{const selected=document.querySelector(`input[name="tf${i}"]:checked`);const ok=!!selected&&(selected.value==='true')===it.a;if(ok){detail.tf++;total+=5;}setEvalFeedback('evalFbTf'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+(it.a?'Verdadero':'Falso'));});d.mc.forEach((it,i)=>{const selected=document.querySelector(`input[name="mc${i}"]:checked`);const ok=!!selected&&Number(selected.value)===it.a;if(ok){detail.mc++;total+=5;}setEvalFeedback('evalFbMc'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.o[it.a]);});const expectedLetters=d.pr.terms.map(it=>d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)]);expectedLetters.forEach((letter,i)=>{const sel=document.querySelector(`[data-pr="${i}"]`);const ok=!!sel&&sel.value===letter;if(sel){sel.classList.toggle('eval-input-ok',ok);sel.classList.toggle('eval-input-no',!ok);}if(ok){detail.pr++;total+=5;}});const prMsg=`Pareados: ${detail.pr}/5 correctos. ${detail.pr===5?'Excelente. +25 pts':'Clave: '+expectedLetters.map((l,i)=>(i+16)+'→'+l).join(' · ')}`;setEvalFeedback('evalFbPr',detail.pr===5,prMsg);const result=document.getElementById('evalAutoResult');if(result){result.className='eval-auto-result '+(total>=70?'eval-auto-pass':'eval-auto-risk');result.innerHTML=`<strong>Resultado automático: ${total}/100 puntos</strong><br><span>Completar: ${detail.cp*5}/25 · V/F: ${detail.tf*5}/25 · Selección: ${detail.mc*5}/25 · Pareados: ${detail.pr*5}/25</span><br><em>Este resultado es solo para revisión en pantalla; la impresión conserva el formato limpio para papel.</em>`;}if(total>=70){pts(8);showToast('🎯 Evaluación calificada: '+total+'/100');}else showToast('🧮 Evaluación calificada: '+total+'/100. Revisa las respuestas marcadas.');}
function printEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const forma=window._currentEvalForm||1;const d=window._evalPrintData;let s1=`<div class="sec-title"><span>I. Completar el espacio</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.cp.forEach((it,i)=>{const q=it.q.replace('___','<span class="cp-blank"></span>');s1+=`<div class="cp-row"><span class="qn">${i+1}.</span><span class="cp-text">${q}</span></div>`;});let s2=`<div class="sec-title"><span>II. Verdadero o Falso</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.tf.forEach((it,i)=>{s2+=`<div class="tf-row"><span class="qn">${i+6}.</span><span class="tf-blank"></span><span class="tf-text">${it.q}</span></div>`;});let s3=`<div class="sec-title"><span>III. Selección Múltiple</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="mc-grid">`;d.mc.forEach((it,i)=>{const opts=it.o.map((op,oi)=>`<label class="mc-opt"><input type="radio" name="mcp${i}"> ${op}</label>`).join('');s3+=`<div class="mc-item"><div class="mc-q"><span class="qn">${i+11}.</span><span>${it.q}</span></div><div class="mc-opts">${opts}</div></div>`;});s3+=`</div>`;let colL='<div class="pr-col"><div class="pr-head">📌 Términos</div>';d.pr.terms.forEach((it,i)=>{colL+=`<div class="pr-item"><span class="pr-num">${i+16}.</span><span class="pr-line"></span>${it.term}</div>`;});colL+='</div>';let colR='<div class="pr-col"><div class="pr-head">🔑 Definiciones</div>';d.pr.shuffledDefs.forEach((it,i)=>{colR+=`<div class="pr-item"><span class="pr-num">${d.pr.letters[i]}.</span>${it.def}</div>`;});colR+='</div>';let s4=`<div class="pr-section"><div class="sec-title"><span>IV. Términos Pareados</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="pr-grid">${colL}${colR}</div></div>`;let pR='';pR+=`<div class="p-sec"><div class="p-ttl">I. Completar</div><table class="p-tbl">`;d.cp.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+1}.</td><td class="pa">${it.a}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">II. V o F</div><table class="p-tbl">`;d.tf.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+6}.</td><td class="pa">${it.a?'V':'F'}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">III. Selección</div><table class="p-tbl">`;d.mc.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+11}.</td><td class="pa">${it.o[it.a]}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">IV. Pareados</div><table class="p-tbl">`;d.pr.terms.forEach((it,i)=>{const l=d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)];pR+=`<tr><td class="pn">${i+16}.</td><td class="pa">${i+16}→${l}</td></tr>`;});pR+=`</table></div>`;const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Evaluación Las seis palancas · Ruta de la Persuasión · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.12rem 0.4rem;margin:0.22rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:58px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.qn{font-weight:700;min-width:22px;flex-shrink:0;}.tf-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.tf-blank{display:inline-block;min-width:40px;border-bottom:1.5px solid #111;flex-shrink:0;margin:0 0.18rem;}.tf-text{flex:1;}.mc-item{border:1px solid #ddd;border-radius:4px;padding:0.14rem 0.35rem;margin-bottom:0.1rem;break-inside:avoid;page-break-inside:avoid;}.mc-q{font-size:10.5pt;line-height:1.3;display:flex;gap:0.28rem;margin-bottom:0.07rem;}.mc-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.1rem 0.5rem;}.mc-opts{display:grid;grid-template-columns:repeat(4,1fr);gap:0.04rem 0.15rem;margin-left:0.8rem;}.mc-opt{font-size:9pt;display:flex;align-items:center;gap:0.15rem;}.mc-opt input{width:10px;height:10px;flex-shrink:0;}.cp-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.cp-text{flex:1;}.cp-blank{display:inline-block;min-width:150px;border-bottom:1.5px solid #111;margin:0 0.12rem;}.pr-section{margin-top:0.1rem;}.pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.08rem 0.4rem;margin-top:0.08rem;}.pr-head{font-size:9pt;font-weight:700;color:#555;margin-bottom:0.1rem;}.pr-item{font-size:10.5pt;padding:0.1rem 0.28rem;background:#ece9fb;border-radius:3px;margin-bottom:0.07rem;display:flex;align-items:center;gap:0.2rem;line-height:1.2;break-inside:avoid;page-break-inside:avoid;}.pr-num{font-weight:700;color:#3b3a86;min-width:19px;flex-shrink:0;}.pr-line{display:inline-block;min-width:19px;border-bottom:1.5px solid #111;margin-right:0.14rem;flex-shrink:0;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.22rem;padding:0.15rem 0;page-break-before:avoid;break-before:avoid;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.25rem 0.4rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.15rem;}.p-tbl{width:100%;border-collapse:collapse;font-size:7.5pt;}.p-tbl tr{border-bottom:1px dotted #ddd;}.p-tbl td{padding:0.07rem 0.12rem;vertical-align:top;}.pn{font-weight:700;width:16px;color:#555;}.pa{color:#007a00;font-weight:600;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Final · Las seis palancas · Ruta de la Persuasión · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Instituto:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · Cada respuesta vale 5 puntos</p></div>${s1}${s2}${s3}${s4}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100%</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Evaluación Final · Las seis palancas · Ruta de la Persuasión · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 4 secciones × 5 preguntas × 5 pts c/u</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;const win=window.open('','_blank','');if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);}

// ===================== PRUEBA DE PENSAMIENTO CRÍTICO =====================
function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un proveedor le deja equipo de muestra en la escuela y a la semana vuelve: \"Después de todo lo que le hemos apoyado, necesito su firma hoy porque el precio cambia mañana\"."},{"txt":"Un asesor le dice: \"Todos los directores del municipio ya adoptaron esta plataforma; usted no querrá ser el único que se quede atrás\"."},{"txt":"Un técnico afirma: \"Esto lo digo como ingeniero con veinte años de experiencia, no hay que darle más vuelta\", y no explica el porqué en términos simples."},{"txt":"Un candidato le recuerda: \"Usted mismo dijo que quería premios para los niños; entonces déjeme poner mi nombre en el torneo, es lo mínimo\"."},{"txt":"Una empresa de tecnología invita al equipo a un almuerzo y a los dos días escribe: \"solo necesitamos que M.E.T.A.S mencione nuestra marca en el manual del maestro, es un detalle\"."},{"txt":"Una autoridad educativa dice: \"esto lo maneja gente que sabe de currículo, no le dé más vuelta\", y pide firmar un convenio de dos años sin dejar copia del texto."}];
const critCaseQuestions=["1. ¿Qué palanca se está usando y con qué frase exacta se activa?","2. ¿Qué información importante NO se está diciendo?","3. Escribe tu respuesta de 3-4 frases: nombra la palanca sin pelear y pon tu condición.","4. ¿En qué versión de esta oferta SÍ dirías sí, y con qué garantía por escrito?"];
const critCaseGuides=["Identifica la frase que activa la palanca: el favor previo (reciprocidad), «todos ya entraron» (prueba social), «como ingeniero» (autoridad), «usted mismo dijo» (coherencia), «mañana cambia» (escasez).","Lo que se omite casi siempre es lo mismo: el costo total, quién responde si falla, qué se compromete a cambio y si el plazo o la lista se pueden verificar.","Respuesta modelo: reconocer lo cierto, nombrar la palanca con calma («esto suena a urgencia, ¿el plazo es real?»), pedir lo que falta por escrito y aplicar las 24 horas. Sin pelear y sin justificarse: la calma es la defensa.","Casi siempre hay una versión aceptable: muestra sin compromiso, piloto pequeño y reversible, lista verificable de referencias, reglas de patrocinio iguales para todos, y todo firmado con fechas y responsables."];

const critErrorBank=[{"txt":"\"Si la técnica funciona, da igual si oculté información: al final los dos ganamos\".","g1":"El resultado no legitima el método: si la otra parte no habría aceptado sabiéndolo todo, el sí no era válido.","g2":"Y el costo llega después: la confianza quemada cuesta años, y en un proyecto educativo la confianza ES el activo."},{"txt":"\"Usar palancas de influencia es manipular; lo correcto es solo dar datos\".","g1":"Nadie decide con datos puros: la palanca aparece igual, se conozca o no. Presentar bien lo verdadero es parte de comunicar.","g2":"La línea no está en usar la palanca, está en si la información completa está sobre la mesa."},{"txt":"\"Si pido 24 horas voy a perder la oportunidad, así que mejor decido ya\".","g1":"Un límite real aguanta un día; si se cae por eso, era presión y no oportunidad.","g2":"El miedo a perder es justamente el mecanismo de la escasez: sentirlo es la señal para frenar, no para firmar."},{"txt":"\"Cuando alguien tiene un título alto, discutirle es falta de respeto\".","g1":"Pedir que explique en una frase simple no es faltar el respeto: es lo que hace cualquiera que va a firmar.","g2":"La autoridad real explica sin molestarse; la prestada se incomoda cuando le piden claridad."},{"txt":"\"Como el patrocinador es amigo de la familia, no hace falta poner las reglas por escrito\".","g1":"La simpatía es justamente la palanca que hace saltarse el papel. Con un amigo el acuerdo escrito protege la amistad, no la ofende.","g2":"Lo que no está escrito se recuerda distinto cuando hay dinero o nombre de por medio, y ahí se pierden las dos cosas: el acuerdo y el amigo."}];

const critDecisionBank=["Una ONG deja 300 tablets de muestra en tres escuelas y después pide el logo en la portada de M.E.T.A.S por dos años: ¿cómo se responde sin que el favor previo decida?","Una dirección departamental dice que «todos los departamentos ya están adoptando plataformas» y pide entrar en 200 escuelas sin pago: ¿qué se verifica antes de aceptar?","Un inversionista da 48 horas para aceptar L 1,200,000 por el 40% del proyecto: ¿qué se hace con ese plazo?","Un candidato ofrece pagar los premios del Campeonísimo y recuerda que usted dijo que quería premios para los niños: ¿cómo se sostiene la coherencia sin ceder el nombre del torneo?","Para convencer a una escuela nueva, se puede exagerar el número de aulas que ya usan M.E.T.A.S o mostrar tres casos verificables: ¿qué cambia a mediano plazo cada camino?","Una editorial presenta su oferta por las fichas con un primer número muy bajo, esperando anclar la negociación: ¿cómo se entra a esa reunión?","Un alcalde ofrece L 250,000 para imprimir fichas de M.E.T.A.S en 40 escuelas y pide que su fotografía vaya en la contraportada, tres meses antes de las elecciones: ¿qué parte se acepta y qué parte no?","Una empresa de telefonía ofrece datos móviles gratis para 500 alumnos a cambio de instalar su aplicación junto a M.E.T.A.S y recibir \"estadísticas de uso\": ¿qué se revisa antes de decir sí?"];
const critDecisionGuide="Una respuesta completa hace cuatro cosas, en este orden. 1) NOMBRA la palanca sin pelear: el favor previo (reciprocidad), «todos ya entraron» (prueba social), «usted mismo dijo» (coherencia), el título o el tecnicismo (autoridad), el plazo (escasez), el primer número (anclaje). 2) SEPARA lo cierto de lo que decide: agradecer el apoyo es correcto, dejar que ese apoyo decida no lo es. 3) PIDE lo que falta por escrito: costo total, quién responde si falla, qué se compromete a cambio, y la lista verificable si se invocó a terceros. 4) PONE LA CONDICIÓN y aplica las 24 horas: casi siempre existe una versión aceptable (piloto pequeño y reversible, reglas iguales para todos, patrocinio sin ceder el nombre). Se descuenta si la respuesta cede, si pelea, o si acepta sin condición escrita. Vale más la condición concreta que el discurso: la calma no es lentitud, es la posición desde donde se ve la palanca.";

const critCompareBank=[{"a":"Presentar M.E.T.A.S con tres escuelas reales, sus cifras y maestros que dan su nombre.","b":"Presentar M.E.T.A.S diciendo que «cientos de aulas ya lo usan», sin lista.","ga":"Caso A: la prueba social es verificable, así que resiste la primera pregunta incómoda y construye reputación acumulada.","gb":"Caso B: convence más rápido y se cae en la primera verificación, arrastrando la credibilidad de todo lo demás.","gr":"La misma palanca sostiene los dos casos; lo que cambia es si hay algo detrás cuando alguien revisa."},{"a":"Pedir 24 horas ante una oferta con plazo.","b":"Decidir en la reunión para no perder la oportunidad.","ga":"Caso A: filtra las urgencias fabricadas sin costo real, porque lo legítimo aguanta un día.","gb":"Caso B: gana velocidad y paga con acuerdos que no se leyeron completos.","gr":"El costo de esperar un día es casi siempre menor que el de un compromiso mal medido."},{"a":"Decir a una escuela: \"M.E.T.A.S no resuelve la conectividad ni sustituye al maestro; resuelve práctica y evaluación sin internet\".","b":"Decir a una escuela: \"M.E.T.A.S resuelve el problema educativo de su centro\".","ga":"Caso A: al nombrar lo que NO hace, vuelve creíble lo que sí hace, y no deja una expectativa que después cobre alguien.","gb":"Caso B: consigue la reunión más rápido y crea una deuda imposible: el primer mes sin internet lo desmiente.","gr":"Prometer menos de lo que se cumple es una palanca lenta que se acumula; prometer de más es un préstamo contra la propia reputación."},{"a":"Aceptar el patrocinio de un candidato con reglas publicadas, iguales para cualquier otro que quiera patrocinar.","b":"Aceptar el patrocinio de un candidato y ponerle su nombre al Campeonísimo.","ga":"Caso A: el proyecto conserva el control de su nombre y puede aceptar al siguiente sin contradecirse.","gb":"Caso B: cambia un ingreso de una vez por el activo que tardó años en construirse, y amarra el torneo a una campaña.","gr":"La diferencia no es el dinero, es qué se entrega a cambio: lo reversible se negocia, el nombre no se recupera."},{"a":"Regalar el kit de capacitación a una escuela sin pedir nada a cambio.","b":"Regalar el kit y a la semana volver a pedir la firma del convenio.","ga":"Caso A: es dar valor real antes de pedir, que es el uso honesto de la reciprocidad.","gb":"Caso B: convierte el mismo regalo en una deuda calculada, y el sí que se consiga no será una decisión sino un pago.","gr":"El regalo es idéntico en los dos casos: lo que cambia es si estaba puesto para ayudar o para cobrar."}];

const critCauseBank=[{"cause":"Se acepta un equipo de regalo antes de negociar el acuerdo.","guide":"La reciprocidad entra al análisis: cada condición que se discuta después va a pesar menos que la deuda que ya se siente."},{"cause":"Se decide en la misma reunión donde apareció el plazo.","guide":"La escasez cumple su función: la decisión se toma con emoción y sin comparar, que es exactamente lo que buscaba la táctica."},{"cause":"Se exagera el número de escuelas para conseguir la primera firma.","guide":"La prueba social inflada funciona una vez; cuando alguien pide la lista, se pierde la firma y la reputación que la sostenía."},{"cause":"Se acepta un tecnicismo sin pedir explicación simple.","guide":"La autoridad decide en tu lugar: se firma algo que no se entiende y el riesgo aparece cuando ya no hay margen."},{"cause":"Se firma un convenio de dos años sin leer la cláusula de exclusividad.","guide":"La autoridad decidió en lugar de quien firma: el costo aparece cuando llega la segunda oportunidad y ya no se puede aceptar."},{"cause":"Se acepta discutir sobre el número que el otro puso primero sobre la mesa.","guide":"El anclaje ya hizo su trabajo: toda la negociación se mueve alrededor de esa cifra, aunque se consigan mejoras parciales."}];
const critEffectBank=[{"effect":"El proveedor retiró la oferta cuando se le pidió un día para pensarla.","guide":"El plazo era fabricado: la presión era el producto. Pedir tiempo no costó una oportunidad, evitó un problema."},{"effect":"Una escuela aceptó el piloto después de que se le dijera con claridad qué NO resuelve el sistema.","guide":"Reconocer los límites aumenta la credibilidad: al no prometer todo, lo prometido se vuelve creíble."},{"effect":"Un director llamó a un maestro de la lista de referencias y al día siguiente firmó.","guide":"Prueba social verificable: la palanca funcionó porque había algo real detrás que resistió la verificación."},{"effect":"Una negociación por las fichas terminó en mejores términos que la primera oferta.","guide":"Se entró con un número propio calculado antes: el anclaje del otro perdió fuerza al no ser el primero sobre la mesa."},{"effect":"Un patrocinador se retiró cuando supo que las mismas reglas aplicaban a todos.","guide":"Lo que buscaba era exclusividad, no apoyar: la regla pública filtró la intención antes de que costara el nombre del proyecto."},{"effect":"Una escuela que había dicho que no volvió a buscar el proyecto seis meses después.","guide":"No se forzó el sí en la primera reunión: al no quedar una promesa incumplida de por medio, la puerta siguió abierta."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Pensamiento Crítico · Forma ${cf} · Las seis palancas · Ruta de la Persuasión`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué palanca está operando, qué harías y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que ceder o que pelear.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué palanca usa cada caso y cuál de los dos resiste que la otra persona lo sepa todo? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Pensamiento crítico: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué palanca está operando, qué harías y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que ceder o que pelear.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué palanca usa cada caso y cuál de los dos resiste que la otra persona lo sepa todo? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Pensamiento Crítico Las seis palancas · Ruta de la Persuasión · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Pensamiento Crítico · Las seis palancas · Ruta de la Persuasión · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Pensamiento Crítico · Las seis palancas · Ruta de la Persuasión · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

