const timelineData=[{"y":"1","icon":"🎁","label":"Reciprocidad","text":"Devolvemos lo que recibimos. <strong>Honesta:</strong> dar valor real antes de pedir (un kit, una capacitación). <strong>Manipulada:</strong> un regalo calculado para que te cueste negarte. <strong>Antídoto:</strong> agradecer el regalo y decidir aparte, como si no existiera."},{"y":"2","icon":"🪜","label":"Compromiso y coherencia","text":"Queremos sostener lo que ya dijimos. <strong>Honesta:</strong> acuerdos por etapas claras. <strong>Manipulada:</strong> arrancar un sí menor para cobrarlo después (pie en la puerta). <strong>Antídoto:</strong> tratar cada petición como nueva."},{"y":"3","icon":"👥","label":"Prueba social","text":"Si otros como yo lo hacen, parece seguro. <strong>Honesta:</strong> resultados reales y verificables. <strong>Manipulada:</strong> cifras infladas y testimonios comprados. <strong>Antídoto:</strong> pedir la lista y hablar con uno de la lista."},{"y":"4","icon":"🎓","label":"Autoridad","text":"Obedecemos señales de experiencia. <strong>Honesta:</strong> competencia comprobable. <strong>Manipulada:</strong> autoridad prestada o lenguaje difícil para que no preguntes. <strong>Antídoto:</strong> pedir que lo explique en una frase simple."},{"y":"5","icon":"🤝","label":"Simpatía","text":"Decimos sí a quien nos cae bien. <strong>Honesta:</strong> trato genuino y respeto. <strong>Manipulada:</strong> halago instrumental y amistad fabricada. <strong>Antídoto:</strong> separar la persona del contenido: ¿aceptaría esto si me lo dijera alguien antipático?"},{"y":"6","icon":"⏳","label":"Escasez","text":"Lo que se puede perder pesa más. <strong>Honesta:</strong> un límite real y verificable. <strong>Manipulada:</strong> urgencia fabricada, «solo hoy», cupos que nunca se acaban. <strong>Antídoto:</strong> la regla de las 24 horas. Si la oferta se cae por eso, era la trampa."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

