const parteData={"urgencia":{"nombre":"Urgencia fabricada","icon":"⏳","estructura":{"title":"Qué es","info":"• Un plazo, un cupo o un precio que <strong>vence pronto</strong><br>• Casi siempre es la primera táctica que aparece en una oferta<br>• Se apoya en la palanca de <strong>escasez</strong>: perder duele más que ganar"},"funcion":{"title":"Cómo funciona","info":"• Saca la decisión del razonamiento y la pasa a la emoción<br>• Impide comparar, consultar y calcular<br>• Se refuerza con «no le puedo garantizar que mañana esté»"},"enfermedades":{"title":"Cómo se detecta","info":"• El plazo <strong>no se puede verificar</strong> con nadie más<br>• Se ofrece antes de que hayas visto los números completos<br>• Cuando pides un día, la respuesta es incomodidad, no información"},"cuidados":{"title":"En el proyecto","info":"• «Este candidato paga los premios, pero tiene que decidir esta semana»: el plazo es de la campaña, no del torneo<br>• Respuesta: reglas públicas de patrocinio y 24 horas para responder, siempre"}},"favor":{"nombre":"El favor previo","icon":"🎁","estructura":{"title":"Qué es","info":"• Un regalo, una muestra, una atención <strong>antes</strong> de pedir<br>• Se apoya en la <strong>reciprocidad</strong>, que es la palanca más antigua<br>• No siempre es mala fe: mucha gente da valor de verdad"},"funcion":{"title":"Cómo funciona","info":"• Crea una deuda que nadie nombró y que pesa al decidir<br>• Cuanto más personal el regalo, más difícil el no<br>• Se activa incluso cuando el regalo es pequeño"},"enfermedades":{"title":"Cómo se detecta","info":"• El regalo llega <strong>antes</strong> de que se hable del acuerdo<br>• Se menciona después, en el momento de pedir<br>• Rechazar el favor incomoda más de lo normal"},"cuidados":{"title":"En el proyecto","info":"• «Le dejo 300 tablets para tres escuelas» seguido de «solo pedimos el logo en la portada»<br>• Respuesta: agradecer, y decidir el logo como si el equipo no existiera. Si el trato es bueno, aguanta esa separación"}},"autoridad":{"nombre":"Autoridad prestada","icon":"🎓","estructura":{"title":"Qué es","info":"• Cargos, títulos, logos de instituciones o <strong>tecnicismos</strong> usados como argumento<br>• A veces la autoridad es real y no explica nada; otras veces es prestada"},"funcion":{"title":"Cómo funciona","info":"• Convierte «no entiendo» en «no debo preguntar»<br>• Traslada la responsabilidad de decidir a quien parece saber<br>• Funciona más fuerte con quien teme quedar en ridículo"},"enfermedades":{"title":"Cómo se detecta","info":"• No se puede explicar <strong>en una frase simple</strong><br>• La credencial no tiene relación con lo que se decide<br>• Se cita a alguien que nunca revisó el acuerdo"},"cuidados":{"title":"En el proyecto","info":"• «Un ingeniero dijo que su sistema no es profesional porque no usa framework»: autoridad sin argumento<br>• Respuesta: los módulos de autocapacitación existen justo para contestar eso con hechos, no con cargos"}},"social":{"nombre":"Prueba social inflada","icon":"👥","estructura":{"title":"Qué es","info":"• Cifras, testimonios o listas que muestran que <strong>otros ya aceptaron</strong><br>• Es la palanca más fácil de exagerar y la más difícil de verificar en el momento"},"funcion":{"title":"Cómo funciona","info":"• Sustituye tu criterio por el del grupo<br>• Da permiso emocional: si todos lo hacen, no puede estar mal<br>• Se combina con escasez: «todos entraron y quedan pocos lugares»"},"enfermedades":{"title":"Cómo se detecta","info":"• No hay <strong>nombres verificables</strong> ni forma de contactarlos<br>• Los testimonios son genéricos y sin cifras<br>• El número redondo y grande aparece sin fuente"},"cuidados":{"title":"En el proyecto","info":"• Del otro lado: M.E.T.A.S sí puede usar esta palanca <strong>con la verdad</strong>, mostrando escuelas reales, resultados medidos y maestros que dan su nombre<br>• Esa es la diferencia: la lista existe y se puede llamar"}}};
let labParte='urgencia',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente arquitecto en formación!','¡Dominas el panorama de M.E.T.A.S!','¡Maestro del Panorama Técnico!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó el Módulo 1 de Autocapacitación M.E.T.A.S (Panorama técnico)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

